(* [comment removed for export] *)
Lemma AImplBlock_mono {HCEIL : HeapCeil} : forall LB LB' m b I, (forall x, In x LB -> In x LB') -> AImplBlock LB m b I -> AImplBlock LB' m b I.
Proof.
  intros LB LB' m b I SUB (p & j7 & IN & RB & CH & OK & EV & PM & CV & LE & ST & AD). exists p, j7.
  split; [apply SUB; exact IN|]. split; [exact RB|]. split; [exact CH|]. split; [exact OK|]. split; [exact EV|]. split; [exact PM|].
  split; [exact CV|]. split; [exact LE|]. split; [| exact AD].
  destruct ST as [ST|(q & junk & INq & K)]; [left; exact ST| right]. exists q, junk. split; [apply SUB; exact INq| exact K].
Qed.

