Lemma AMiscVt48_of_AXImg {HCEIL : HeapCeil} : forall m, AXImg m -> AMiscVt48 m.
Proof.
  intros m XI. pose proof (chunk_of_AXImg m (AW_MISC_CAT_VT48, [P_A_ECAT_FAILED]) XI ltac:(vm_compute; reflexivity)) as K.
  cbn [fst snd wcells map] in K. exact (proj1 K).
Qed.

(* [comment removed for export] *)
Lemma hz_sh3_ec {HCEIL : HeapCeil} : forall m A, rw_cells bsegs m A hz_sh3 -> rw_cells bsegs m (A + 8) [CB 3 (poison_bytes 3 0)].
Proof.
  intros m A SH. unfold hz_sh3, hz_sh in SH.
  apply (proj1 (rw_cells_app bsegs m A [_; _; _] _)) in SH. destruct SH as [_ SH]. cbn [cells_size csize Nat.add] in SH.
  apply (proj1 (rw_cells_app bsegs m _ [_] _)) in SH. destruct SH as [SH _].
  replace (A + Z.of_nat 8) with (A + 8) in SH by lia. exact SH.
Qed.
Lemma hz_sh3_fb {HCEIL : HeapCeil} : forall m A, rw_cells bsegs m A hz_sh3 -> rw_cells bsegs m (A + 16) [CB 6 (poison_bytes 6 0)].
Proof.
  intros m A SH. unfold hz_sh3, hz_sh in SH.
  apply (proj1 (rw_cells_app bsegs m A [_; _; _; _; _] _)) in SH. destruct SH as [_ SH]. cbn [cells_size csize Nat.add] in SH.
  apply (proj1 (rw_cells_app bsegs m _ [_] _)) in SH. destruct SH as [SH _].
  replace (A + Z.of_nat 16) with (A + 16) in SH by lia. exact SH.
Qed.

